// Code by Flopine

// Thanks to wsmind, leon, XT95, lsdlive, lamogui, 
// Coyhot, Alkama,YX, NuSan, slerpy, wwrighter 
// BigWings, FabriceNeyret and Blackle for teaching me

// Thanks LJ for giving me the spark :3

// Thanks to the Cookie Collective, which build a cozy and safe environment for me 
// and other to sprout :)  
// https://twitter.com/CookieDemoparty

// Genuary #13: Triangles and nothing else
// Based on Fabrice's shader: https://www.shadertoy.com/view/4dKXR3


#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))
#define PI acos(-1.)
#define noi(u) textureLod(iChannel0, u, 0.).x

// https://iquilezles.org/articles/distfunctions/
float sdTriPrism( vec3 p, vec2 h )
{
  vec3 q = abs(p);
  return max(q.z-h.y,max(q.x*0.866025+p.y*0.5,-p.y)-h.x*0.5);
}

vec3 id=vec3(0.);
float SDF (vec3 p)
{
    p.yz *= rot(-atan(1./sqrt(2.)));
    p.xz *= rot(PI/4.);

    vec2 uv = p.xz; 
    uv *= mat2(1, -1./sqrt(3.), 0, 2./sqrt(3.))*5.; // skew UVs
    vec3 g = vec3(uv, 1.-uv.x-uv.y); // split skews to triangle
    id = floor(g); // cell id

    vec2 lu = fract(uv)-.5;
    float s = (lu.x > -lu.y) ? 1. : -1.;
    lu *= inverse(mat2(1, -1./sqrt(3.), 0, 2./sqrt(3.)));
    lu -= vec2(.25, .14)*s; // magic numbers... I guess there's an explanation
    lu.y *= -s;

    return sdTriPrism(vec3(lu, p.y), vec2(.45, sin(length(id*.3)-iTime*2.)*.08+.04))-0.02;
}

vec3 getn (vec3 p)
{
    vec2 eps = vec2(.01, 0.);
    return normalize(SDF(p)-vec3(SDF(p-eps.xyy), SDF(p-eps.yxy), SDF(p-eps.yyx)));
}

float AO (vec3 p, vec3 n, float e)
{return clamp(SDF(p+e*n)/e, 0., 1.);}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-iResolution.xy/2.)/iResolution.y;
    vec3 ro=vec3(uv*1.5, -30.), rd=vec3(0., 0., 1.), p=ro,
    col=vec3(0.);

    bool hit=false;
    for (float i=0.; i<80.; i++)
    {
        float d = SDF(p);
        if(d<0.001)
        {
            hit = true; 
            break;
        }
        p += d*rd*.3;
    }

    if (hit)
    {
        vec3 n = getn(p);
        float ao = AO(p, n, 0.15)+AO(p, n, 0.2)+AO(p, n, 0.3);
        float nid = noi(id*.27);
        col = vec3(nid*.99, 1., nid*.3)+ao/4.;
    }

    fragColor = vec4(sqrt(clamp(col, 0., 1.)),1.0);
}
